exercise.referenceSolution:
#include <stdio.h>
#include <string.h>

#define CR1_UE (1u << 0)
#define CR1_RE (1u << 2)
#define CR1_TE (1u << 3)
#define CR1_PS (1u << 9)
#define CR1_PCE (1u << 10)
#define CR1_M (1u << 12)
#define CR2_STOP_POS 12

int main(void) {
    unsigned long clock, baud;
    char parity[8], stop[8], mode[8];
    while (scanf("%lu %lu %7s %7s %7s", &clock, &baud, parity, stop, mode) == 5) {
        unsigned long brr = (clock + baud / 2) / baud;
        if (brr < 16 || brr > 65535) {
            printf("ошибка: недостижимая скорость\n");
            continue;
        }
        unsigned cr1 = CR1_UE;
        if (strcmp(mode, "rx") == 0 || strcmp(mode, "rxtx") == 0) {
            cr1 |= CR1_RE;
        }
        if (strcmp(mode, "tx") == 0 || strcmp(mode, "rxtx") == 0) {
            cr1 |= CR1_TE;
        }
        if (strcmp(parity, "none") != 0) {
            cr1 |= CR1_PCE | CR1_M;
            if (strcmp(parity, "odd") == 0) {
                cr1 |= CR1_PS;
            }
        }
        unsigned stop_code = strcmp(stop, "0.5") == 0   ? 1u
                             : strcmp(stop, "2") == 0   ? 2u
                             : strcmp(stop, "1.5") == 0 ? 3u
                                                        : 0u;
        unsigned cr2 = stop_code << CR2_STOP_POS;
        unsigned long actual = clock / brr;
        unsigned long diff = actual > baud ? actual - baud : baud - actual;
        double error = (double)diff * 100.0 / (double)baud;
        printf("CR1=0x%04X CR2=0x%04X BRR=%lu скорость=%lu ошибка=%.2f%%\n", cr1, cr2, brr, actual,
               error);
    }
    return 0;
}

additionalExercises.description:
Смоделируйте 16-битный регистр выхода порта `ODR` и регистр установки и сброса `BSRR`. Вначале `ODR = 0`. Команды до конца ввода:
- `odr 0xHHHH` — записать значение в `ODR` напрямую;
- `bsrr 0xHHHHHHHH` — запись в `BSRR`: единица в бите `n` (0–15) устанавливает ножку `n`, единица в бите `n + 16` сбрасывает её; если для ножки установлены оба бита, побеждает установка;
- `make 0xHHHH` — вычислить и напечатать значение `BSRR=0xHHHHHHHH`, которое одной записью превращает текущий `ODR` в заданное значение, меняя только нужные ножки (единицы только для ножек, которые меняются), и применить его;
- `show` — напечатать `ODR=0xHHHH` и номера ножек с высоким уровнем: `высокие: 1 4` или `высоких нет`.

Шестнадцатеричные цифры печатайте заглавными.

