additionalExercises.referenceSolution:
#include <stdint.h>
#include <stdio.h>
#include <string.h>

static uint32_t odr;

static void bsrr_write(uint32_t value) {
    uint32_t set = value & 0xFFFFu;
    uint32_t reset = value >> 16;
    odr = ((odr & ~reset) | set) & 0xFFFFu;
}

int main(void) {
    char command[16];
    while (scanf("%15s", command) == 1) {
        unsigned value;
        if (strcmp(command, "odr") == 0 && scanf("%x", &value) == 1) {
            odr = value & 0xFFFFu;
        } else if (strcmp(command, "bsrr") == 0 && scanf("%x", &value) == 1) {
            bsrr_write(value);
        } else if (strcmp(command, "make") == 0 && scanf("%x", &value) == 1) {
            uint32_t target = value & 0xFFFFu;
            uint32_t set = target & ~odr;
            uint32_t reset = odr & ~target;
            uint32_t bsrr = reset << 16 | set;
            printf("BSRR=0x%08X\n", (unsigned)bsrr);
            bsrr_write(bsrr);
        } else if (strcmp(command, "show") == 0) {
            printf("ODR=0x%04X ", (unsigned)odr);
            if (odr == 0) {
                printf("высоких нет\n");
                continue;
            }
            printf("высокие:");
            for (int pin = 0; pin < 16; pin++) {
                if ((odr >> pin) & 1u) {
                    printf(" %d", pin);
                }
            }
            printf("\n");
        }
    }
    return 0;
}

