#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define FLAG_TX (1u << 0)        // передача завершена
#define FLAG_RX (1u << 1)        // пришёл байт
#define FLAG_ERR (1u << 2)       // ошибка кадра

// ---- модель устройства (не меняйте) ----
static uint32_t sr_reg;                                  // регистр состояния
static uint32_t sr_read(void) { return sr_reg; }
static void sr_write(uint32_t value) { sr_reg &= ~value; } // W1C: единица сбрасывает флаг
static void hw_raise(uint32_t flags) { sr_reg |= flags; }  // устройство сообщает о событиях
// ---- конец модели ----

static void clear_flag(uint32_t flag) {
    sr_write(sr_read() | flag);           // как SR |= flag
}

static const struct {
    uint32_t flag;
    const char *name;
} EVENT_NAMES[] = {{FLAG_ERR, "ERR"}, {FLAG_RX, "RX"}, {FLAG_TX, "TX"}};   // по приоритету

// Обрабатывает одно событие с наибольшим приоритетом.
static void service(void) {
    uint32_t status = sr_read();
    for (int i = 0; i < 3; i++) {
        if (status & EVENT_NAMES[i].flag) {
            printf("обработано: %s\n", EVENT_NAMES[i].name);
            clear_flag(EVENT_NAMES[i].flag);
            return;
        }
    }
    printf("событий нет\n");
}

int main(void) {
    char command[16], name[16];
    while (scanf("%15s", command) == 1) {
        if (strcmp(command, "raise") == 0 && scanf("%15s", name) == 1) {
            for (int i = 0; i < 3; i++) {
                if (strcmp(EVENT_NAMES[i].name, name) == 0) {
                    hw_raise(EVENT_NAMES[i].flag);
                }
            }
        } else if (strcmp(command, "service") == 0) {
            service();
        } else if (strcmp(command, "pending") == 0) {
            printf("SR=0x%X\n", (unsigned)sr_read());
        }
    }
    return 0;
}

