#include <stdint.h>
#include <stdio.h>

// ---- модель приёмника (не меняйте) ----
#define UART_RXNE (1u << 5)                 // в очереди есть байт
static char fifo[4096];
static size_t fifo_len, fifo_pos;

static uint32_t uart_sr(void) {
    return fifo_pos < fifo_len ? UART_RXNE : 0;
}

static uint32_t uart_dr(void) {             // чтение регистра данных забирает байт из очереди
    return fifo_pos < fifo_len ? (unsigned char)fifo[fifo_pos++] : 0;
}

#define UART_SR (uart_sr())
#define UART_DR (uart_dr())
// ---- конец модели ----

int main(void) {
    fifo_len = fread(fifo, 1, sizeof fifo, stdin);
    char line[256];
    size_t n = 0;
    int lines = 0;
    while (UART_SR & UART_RXNE) {
        if (UART_DR == '\r') {
            continue;
        }
        if (UART_DR == '\n') {
            line[n] = '\0';
            printf("строка %d: %s\n", ++lines, line);
            n = 0;
            continue;
        }
        if (n < sizeof line - 1) {
            line[n++] = (char)UART_DR;
        }
    }
    if (n > 0) {
        line[n] = '\0';
        printf("строка %d: %s\n", ++lines, line);
    }
    printf("строк: %d\n", lines);
    return 0;
}

